// Full actual native linear TT endpoint hierarchy; AD only, no evolved fields.
#include "goal1_tensor_endpoint_amplitude.hpp"
#include <iostream>
#include <iomanip>
#include <string>
#include <cstdlib>
namespace cs=cubed_sphere;namespace te=cs::tensor_endpoint;namespace h=z4c::hyperboloidal;
Real Read(){std::string s;if(!(std::cin>>s))throw std::runtime_error("short TT endpoint input");char*end;Real x=std::strtod(s.c_str(),&end);if(*end||!std::isfinite(x))throw std::runtime_error("invalid TT endpoint token");return x;}
struct Result{std::array<Real,22>f;Real df[13][3]{};Real pole=0,tangent=0,second=0,time=0,null=0,z=0,negative=0;};
Result Evaluate(const h::Z4cJet<Real>&du,const h::LayerPoint<Real>&p,const Real x[3],Real unused=0){auto parts=te::LinearParts(du,p,x,unused);Result out{};Real norm=0;for(int d=0;d<3;++d)norm+=p.domega[d]*p.domega[d];
 for(int n=0;n<22;++n){auto s=parts.pole[n].a;Real q=0;for(int d=0;d<3;++d)q+=p.domega[d]*s.d[d]/norm;out.f[n]=parts.regular[n].a.f+q;out.pole=std::max(out.pole,std::abs(s.f));for(int d=0;d<3;++d)out.tangent=std::max(out.tangent,std::abs(s.d[d]-p.domega[d]*q));}
 for(int a=0;a<13;++a){int n=cs::native_endpoint::first_rows[a];auto s=parts.pole[n].a;Real q=out.f[n]-parts.regular[n].a.f,R[3][3]{},nn=0,dq[3]{};for(int i=0;i<3;++i)for(int j=0;j<3;++j){R[i][j]=s.h[i][j]-p.omega_hessian[i][j]*q;nn+=p.domega[i]*p.domega[j]*R[i][j];}for(int j=0;j<3;++j){for(int i=0;i<3;++i)dq[j]+=p.domega[i]*R[i][j]/norm;dq[j]-=p.domega[j]*nn/(2*norm*norm);out.df[a][j]=parts.regular[n].a.d[j]+dq[j];}for(int i=0;i<3;++i)for(int j=0;j<3;++j)out.second=std::max(out.second,std::abs(R[i][j]-p.domega[i]*dq[j]-p.domega[j]*dq[i]));}
 h::Z4cJet<Real>rate{};rate.chi.value=out.f[0];rate.trace.value=out.f[7];rate.theta.value=out.f[17];rate.alpha.value=out.f[18];for(int n=0;n<6;++n){int i=cs::native_endpoint::ma[n],j=cs::native_endpoint::mb[n];rate.metric.g[i][j]=rate.metric.g[j][i]=out.f[1+n];rate.a.k[i][j]=rate.a.k[j][i]=out.f[8+n];}for(int i=0;i<3;++i){rate.lambda.value[i]=out.f[14+i];rate.beta.value[i]=out.f[19+i];}
 for(int a=0;a<13;++a)for(int d=0;d<3;++d){int n=cs::native_endpoint::first_rows[a];Real v=out.df[a][d];if(n==0)rate.chi.d[d]=v;else if(n>=1&&n<=6){int i=cs::native_endpoint::ma[n-1],j=cs::native_endpoint::mb[n-1];rate.metric.dg[d][i][j]=rate.metric.dg[d][j][i]=v;}else if(n==7)rate.trace.d[d]=v;else if(n==17)rate.theta.d[d]=v;else if(n==18)rate.alpha.d[d]=v;else rate.beta.d[d][n-19]=v;}
 auto time=te::LinearParts(rate,p,x);for(auto s:time.pole)out.time=std::max(out.time,std::abs(s.a.f));auto geometry=h::Geometry(time.state.metric);te::D null=-time.normal*time.normal;for(int i=0;i<3;++i){out.z=std::max(out.z,std::abs((time.state.lambda.value[i]-geometry.contracted[i]).a.f/2));for(int j=0;j<3;++j)null+=time.state.chi.value*geometry.inverse[i][j]*te::D(p.domega[i]*p.domega[j]);}out.null=std::abs(null.a.f);
 auto bad=rate;for(int d=0;d<3;++d)for(int i=0;i<3;++i)for(int j=0;j<3;++j)bad.metric.dg[d][i][j]=0;auto omitted=te::LinearParts(bad,p,x);for(auto s:omitted.pole)out.negative=std::max(out.negative,std::abs(s.a.f));return out;
}
int main(int argc,char**argv){Kokkos::initialize(argc,argv);std::cout<<std::setprecision(17);int status=0;try{while(std::cin>>std::ws,std::cin.peek()!=EOF){int id=Read();Real x[3];for(auto&v:x)v=Read();h::Z4cJet<Real>empty{};auto du=cs::typed_support::Map<Real>(empty,[](int,Real){return Read();});Real target[22],first[13][3];for(auto&v:target)v=Read();for(auto&v:first)for(auto&z:v)z=Read();h::LayerReference<Real>ref(1.,.5,{true,.05,.95});auto p=ref.At(x[0],x[1],x[2]);auto r=Evaluate(du,p,x),changed=Evaluate(du,p,x,.123);Real error=0,gradient=0,invariance=0;auto scaled=[](Real x,Real y){return std::abs(x-y)/std::max({Real(1),std::abs(x),std::abs(y)});};for(int n=0;n<22;++n){error=std::max(error,scaled(r.f[n],target[n]));invariance=std::max(invariance,std::abs(r.f[n]-changed.f[n]));}for(int a=0;a<13;++a)for(int d=0;d<3;++d){gradient=std::max(gradient,scaled(r.df[a][d],first[a][d]));invariance=std::max(invariance,std::abs(r.df[a][d]-changed.df[a][d]));}std::cout<<"{\"id\":"<<id<<",\"native22_scaled\":"<<error<<",\"native13_gradient_scaled\":"<<gradient<<",\"pole\":"<<r.pole<<",\"tangent\":"<<r.tangent<<",\"second_compatibility\":"<<r.second<<",\"pole_time\":"<<r.time<<",\"nullness_time\":"<<r.null<<",\"Z_time\":"<<r.z<<",\"unsupported_higherjet_invariance\":"<<invariance<<",\"negative_omit_metric_gradient_time\":"<<r.negative<<"}\n";}}catch(const std::exception&e){std::cerr<<e.what()<<'\n';status=1;}Kokkos::finalize();return status;}
